#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Entities;
using MVZ2.GameContent.Enemies;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Buffs;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Enemies
{

    [AutoBuffDefinition(VanillaBuffNames.Enemy.bubbleGunUser)]
    public class BubbleGunUserBuff : AIEntityBehaviourBuff
    {
        public BubbleGunUserBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override void UpdateAI(Buff buff, Entity entity)
        {
            switch (entity.State)
            {
                case STATE_WALK:
                    UpdateWalkState(buff, entity);
                    break;
            }
        }
        public override void UpdateLogic(Buff buff, Entity entity)
        {
            base.UpdateLogic(buff, entity);
            entity.SetModelProperty("NoBubbleGun", !HasBubbleGun(entity));
        }
        private void UpdateWalkState(Buff buff, Entity entity)
        {
            if (!HasBubbleGun(buff))
                return;
            var stateTimer = GetOrCreateFireTimerSeconds(buff, HOOK_COOLDOWN_SECONDS);
            var attackSpeed = entity.GetAttackSpeed();
            if (stateTimer.RunToExpiredAndNotNull(attackSpeed))
            {
                stateTimer.ResetSeconds(HOOK_COOLDOWN_SECONDS);
                FireBubble(buff, entity);
            }
        }
        private void FireBubble(Buff buff, Entity entity)
        {
            var point = GetBubbleGunPoint(entity);
            var bubble = entity.SpawnWithParams(VanillaEnemyID.bubble, point);
            if (bubble != null)
            {
                bubble.PlaySound(VanillaSoundID.bubbleSpawn);
                bubble.AddBuff<ReleasedFromLockedChestBuff>();
            }
        }
        public static Vector3 GetBubbleGunPoint(Entity entity)
        {
            if (!entity.IsEntityOf(VanillaEnemyID.bubbleGunGurgle) || !HasBubbleGun(entity))
                return entity.GetCenter();
            var offset = bubbleOffset;
            offset.x *= entity.GetFacingX();
            return entity.Position + offset;
        }
        public static void SetFireTimer(Buff buff, FrameTimer timer) => buff.SetProperty(PROP_FIRE_TIMER, timer);
        public static FrameTimer? GetFireTimer(Buff buff) => buff.GetProperty<FrameTimer>(PROP_FIRE_TIMER);
        public static FrameTimer GetOrCreateFireTimerSeconds(Buff buff, float seconds) => buff.GetOrCreateTimerSeconds(PROP_FIRE_TIMER, seconds);

        public static void SetHasBubbleGun(Buff buff, bool timer) => buff.SetProperty(PROP_HAS_BUBBLE_GUN, timer);
        public static bool HasBubbleGun(Buff buff) => buff.GetProperty<bool>(PROP_HAS_BUBBLE_GUN);
        public static bool HasBubbleGun(IBuffTarget target) => target.GetFirstBuffProperty<HookshotUserBuff, bool>(PROP_HAS_BUBBLE_GUN);

        public static readonly PropertyMeta<FrameTimer> PROP_FIRE_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("fire_timer");
        public static readonly PropertyMeta<bool> PROP_HAS_BUBBLE_GUN = new VanillaBuffPropertyMeta<bool>("has_bubble_gun", true);
        private const float HOOK_COOLDOWN_SECONDS = 6f;
        private static readonly Vector3 bubbleOffset = new Vector3(30, 34, 0);
        public const int STATE_WALK = LogicEnemyStates.WALK;
    }
}
